        const passed = nodeA.hasLease === false && writeOutcome === 'WRITE_BLOCKED';
        return {
            drillId: 'DRILL-1-DB-CRASH',
            scenario: 'Primary DB crash during active lease',
            verdict: passed ? 'PASSED' : 'FAILED',
